using Microsoft.EntityFrameworkCore; using Microsoft.EntityFrameworkCore.Metadata.Builders; using ShikshaMitra.Students.StudentEnrollments.Admissions; using Volo.Abp.EntityFrameworkCore.Modeling;
namespace ShikshaMitra.EntityFrameworkCore.Students.StudentEnrollments.Admissions;
public class AdmissionFormConfiguration : IEntityTypeConfiguration<AdmissionFormDefinition>, IEntityTypeConfiguration<AdmissionFormSectionDefinition>, IEntityTypeConfiguration<AdmissionFormFieldDefinition>
{
	public void Configure(EntityTypeBuilder<AdmissionFormDefinition> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionFormDefinitions", ShikshaMitraConsts.DbSchema); b.ConfigureByConvention(); b.ConfigureSoftDeleteDefault(); b.Property(x => x.Name).IsRequired().HasMaxLength(128); b.Property(x => x.Code).IsRequired().HasMaxLength(64); b.Property(x => x.Description).HasMaxLength(1024); b.Property(x => x.FieldsPerRow).IsRequired().HasDefaultValue(1); b.HasIndex(x => new { x.TenantId, x.Code, x.Version }).IsUnique().HasFilter("\"IsDeleted\" = false"); b.HasIndex(x => new { x.TenantId, x.Code, x.Status }); }
	void IEntityTypeConfiguration<AdmissionFormSectionDefinition>.Configure(EntityTypeBuilder<AdmissionFormSectionDefinition> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionFormSections", ShikshaMitraConsts.DbSchema); b.HasKey(x => x.Id); b.Property(x => x.Code).IsRequired().HasMaxLength(64); b.Property(x => x.Name).IsRequired().HasMaxLength(128); b.Property(x => x.StepCode).HasMaxLength(64); b.Property(x => x.StepName).HasMaxLength(128); b.Property(x => x.StepVisibilityRuleJson).HasMaxLength(8000); b.HasIndex(x => new { x.FormDefinitionId, x.Code }).IsUnique(); b.HasIndex(x => new { x.FormDefinitionId, x.StepId, x.StepDisplayOrder }).HasDatabaseName("IX_AppAdmissionFormSections_Form_Step_Order"); }
	void IEntityTypeConfiguration<AdmissionFormFieldDefinition>.Configure(EntityTypeBuilder<AdmissionFormFieldDefinition> b) { b.ToTable(ShikshaMitraConsts.DbTablePrefix + "AdmissionFormFields", ShikshaMitraConsts.DbSchema); b.HasKey(x => x.Id); b.Property(x => x.Code).IsRequired().HasMaxLength(64); b.Property(x => x.Label).IsRequired().HasMaxLength(128); b.Property(x => x.BindingKey).HasMaxLength(128); b.Property(x => x.OptionsJson).HasMaxLength(8000); b.Property(x => x.ValidationJson).HasMaxLength(8000); b.Property(x => x.VisibilityRuleJson).HasMaxLength(8000); b.Property(x => x.RequiredRuleJson).HasMaxLength(8000); b.HasIndex(x => new { x.FormDefinitionId, x.Code }).IsUnique(); b.HasOne<AdmissionFormDefinition>().WithMany().HasForeignKey(x => x.FormDefinitionId).OnDelete(DeleteBehavior.Cascade); b.HasOne<AdmissionFormSectionDefinition>().WithMany().HasForeignKey(x => x.SectionId).OnDelete(DeleteBehavior.Cascade); }
}
